aws-composite-availability.solution:
def compositeAvailability(design):
    def avail(node):
        if isinstance(node, (int, float)):
            return node / 100.0
        kind, parts = node
        if kind == "serial":
            a = 1.0
            for p in parts:
                a *= avail(p)
            return a
        fail = 1.0
        for p in parts:
            fail *= 1.0 - avail(p)
        return 1.0 - fail
    a = avail(design)
    return [a * 100.0, (1.0 - a) * 525600.0]

